pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(0));
        // owner is address(0) initially; only address(0) passes onlyOwner.
        address firstOwner = address(0xdead);
        vm.prank(address(0));
        c.transferOwnership(firstOwner);

        vm.prank(attacker);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == firstOwner);
    }
}

