pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // wide admissible domain: any actor, any new owner (self-transfers included)
        address oldOwner = c.owner();

        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after the attempt, the owner is newOwner exactly when
        // the current owner successfully transferred; a call by anyone else
        // must not leave the contract owned by newOwner.
        if (ok) {
            assertTrue(actor == oldOwner && c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == oldOwner);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // No domain narrowing: any caller (including the zero address, which is
        // the contract's initial owner) and any new owner are admissible.
        address ownerBefore = c.owner();

        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for EVERY caller, either ownership is untouched, or the
        // caller was the pre-call owner and ownership now equals the new owner.
        assertTrue(
            ok ? (caller == ownerBefore && c.owner() == newOwner)
               : (c.owner() == ownerBefore),
            "ownership changed by a call that was not a successful owner transfer"
        );
    }
}

